const key='marketplace.seller.demo-session';
let session=false;try{sessionStorage.removeItem(key);sessionStorage.removeItem('temlogoali.seller-context')}catch{}
if(typeof window!=='undefined')window.addEventListener('pageshow',e=>{if(e.persisted){endSellerSession();location.reload()}});
export function hasSellerSession(){try{return session||sessionStorage.getItem(key)==='active'}catch{return session}}
export function endSellerSession(){session=false;try{sessionStorage.removeItem(key)}catch{}}
export function showSellerLogin(onSuccess){
  document.title='Entrar · Central de Vendedores';
  document.querySelector('#portal').innerHTML=`<div class="utility"><div class="wrap">PRÉVIA · Acesso demonstrativo, sem autenticação no servidor.</div></div><header class="seller-header wrap"><a class="brand" href="./index.html">tem logo <strong>ali.</strong></a><a class="text-link" href="./index.html">← Voltar às compras</a></header><main class="login-layout wrap"><section class="login-story"><span class="eyebrow">CENTRAL DE VENDEDORES</span><h1>Seu próximo dia<br>de vendas<br><em>começa aqui.</em></h1><p>Entre para cuidar dos seus produtos, acompanhar pedidos e estar mais perto dos seus clientes.</p><div class="login-benefit"><b>Uma central. Sua operação inteira.</b><span>Catálogo, logística, financeiro e equipe em um só lugar.</span></div><div class="login-story-footer">Cianorte, Maringá e região.<br>Feito para o comércio que está perto.</div></section><section class="login-card" aria-labelledby="login-title"><span class="eyebrow">BEM-VINDO DE VOLTA</span><h2 id="login-title">Entre na sua conta</h2><p class="login-description">Acesse a Central de Vendedores da sua loja.</p><form id="seller-login"><label class="field-label" for="seller-email">E-mail<input class="panel-input" id="seller-email" name="email" type="email" autocomplete="username" placeholder="seuemail@empresa.com.br" required></label><label class="field-label" for="seller-password">Senha</label><div class="password-field"><input class="panel-input" id="seller-password" name="password" type="password" autocomplete="current-password" placeholder="Digite sua senha" required><button type="button" id="toggle-password" aria-label="Mostrar senha" aria-pressed="false">Mostrar</button></div><div class="login-options"><button type="button" class="text-link" id="recover-password">Esqueci minha senha</button></div><p id="login-error" class="login-error" role="alert"></p><button class="btn login-submit" type="submit">Entrar na Central de Vendedores →</button></form><div id="recovery-note" class="seller-note" hidden><b>Recuperação de acesso</b><p>O envio de e-mail será conectado na implementação da autenticação. Nesta prévia, use os dados demonstrativos abaixo. Nenhuma mensagem será enviada.</p></div><div class="login-demo"><b>Experimente com uma conta fictícia</b><p>E-mail: <code>lojista@exemplo.com</code><br>Senha: <code>Demo123!</code></p><button class="btn secondary" id="fill-demo" type="button">Entrar com conta de demonstração</button><small>Não utilize sua senha real. Apenas o estado de acesso é mantido nesta aba; a senha não é armazenada.</small></div><p class="login-signup">Ainda não vende com a gente?<br><a href="./vender.html#cadastro">Cadastre sua loja →</a></p></section></main>`;
  const form=document.querySelector('#seller-login'),email=document.querySelector('#seller-email'),password=document.querySelector('#seller-password'),error=document.querySelector('#login-error');
  document.querySelector('#toggle-password').onclick=e=>{const visible=password.type==='password';password.type=visible?'text':'password';e.target.textContent=visible?'Ocultar':'Mostrar';e.target.setAttribute('aria-label',visible?'Ocultar senha':'Mostrar senha');e.target.setAttribute('aria-pressed',String(visible))};
  document.querySelector('#fill-demo').onclick=()=>{email.value='lojista@exemplo.com';password.value='Demo123!';error.textContent='';form.requestSubmit()};
  document.querySelector('#recover-password').onclick=()=>{const note=document.querySelector('#recovery-note');note.hidden=!note.hidden};
  form.addEventListener('input',()=>{error.textContent='';email.removeAttribute('aria-invalid');password.removeAttribute('aria-invalid')});
  form.addEventListener('submit',e=>{e.preventDefault();if(email.value.trim().toLowerCase()!=='lojista@exemplo.com'||password.value!=='Demo123!'){error.textContent='E-mail ou senha não conferem. Utilize a conta de demonstração informada abaixo.';email.setAttribute('aria-invalid','true');password.setAttribute('aria-invalid','true');password.focus();return}session=true;try{sessionStorage.setItem(key,'active')}catch{}form.reset();onSuccess();window.scrollTo(0,0)});
}
